let value = 42;
console.log(typeof value); // 'number'

value = 'forty-two';
console.log(typeof value); // 'string' — reassignment changed type

function add(a, b) {
  return a + b; // no type declaration — could concat or add
}

console.log(add(2, 3));    // 5
console.log(add('2', '3')); // '23' — same function, different behavior

// TypeScript — compile-time errors:
let count: number = 10;
// count = 'ten'; // Error TS2322: Type 'string' is not assignable to type 'number'

function greet(name: string): string {
  return `Hello, ${name}`;
}
// greet(42); // Error TS2345: Argument of type 'number' is not assignable

// Compiles to plain JS — types erased:
// let count = 10;
