// C# — compile-time AND run-time types:
int count = 10;
// count = "ten"; // CS0029: Cannot implicitly convert string to int

string Greet(string name) => $"Hello, {name}";
// Greet(42); // CS1503: Argument 1: cannot convert int to string

object boxed = 42;
// string s = (string)boxed; // InvalidCastException at RUN TIME

// TypeScript types do not survive JSON.parse:
const raw = '{"age": "twenty"}'; // string where number expected
const data = JSON.parse(raw);

// Run-time schema validation (e.g. Zod pattern):
function parseUser(input) {
  if (typeof input !== 'object' || input === null) {
    throw new TypeError('Expected object');
  }
  if (typeof input.age !== 'number') {
    throw new TypeError(`age must be number, got ${typeof input.age}`);
  }
  return { age: input.age };
}

try {
  parseUser(JSON.parse(raw));
} catch (e) {
  console.error(e.message); // age must be number, got string
}
